      var _ord = _sl.concat(_so.slice(_k), _so.slice(0, _k)), _n3 = _ord.length, _p3 = ((relWk - 1) * 5) % _n3, _rot3 = [];
      for (var _r3 = 0; _r3 < _n3; _r3++) _rot3.push(_ord[(_r3 - _p3 + _n3) % _n3]);
