    if (lnum) parent = parent.slice(0, parent.lastIndexOf("\n</body>")) + "\n" + lntPkAnswers(weekNum, weekDates, lnum, T) + "\n</body>\n</html>";   // NBLADNUM: the answers, last in the guide

