      var fs = (cur.flag && cur.flag[sub]) || {}, sc = (cur.flagScore && cur.flagScore[sub]) || {};
      var names = Object.keys(fs).sort(function (a, b) { return (sc[b] || 0) - (sc[a] || 0); });
