  var NB_SAY_WORDS = { "+": "plus", "−": "minus", "-": "minus", "–": "minus", "=": "equals", "→": "goes to", "×": "times", "÷": "divided by", "<": "is less than", ">": "is more than", "?": "box" };
  // one printed line → words: numbers in a row are a list ("10, 11, 12"); each [a → b] is its own sentence
