      if (!choices || ord.length !== L.length || ord.split("").sort().join("") !== L || L.indexOf(ans) < 0) return null;
      var byL = {}; choices.forEach(function (c) { byL[c.l] = c.t; });
      return [ord.split("").map(function (o, k) { return { l: L.charAt(k), t: byL[o] }; }), L.charAt(ord.indexOf(ans))];
